const response = $json.data || $json;
// For the OpenAI Chat node, content is often in `response[0].content[0].text` or similar depending on n8n version.
// Adjust this based on the exact output you see in "ChatGPT Parse Order" test.

let text;
if (Array.isArray(response) && response[0]?.message?.content) {
  text = response[0].message.content;
} else if (Array.isArray(response) && response[0]?.content?.[0]?.text) {
  text = response[0].content[0].text;
} else if (typeof response === 'string') {
  text = response;
} else if ($json.message && typeof $json.message === 'string') {
  text = $json.message;
}

if (!text) {
  throw new Error('Could not find ChatGPT text content to parse.');
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Failed to parse JSON from ChatGPT: ' + e.message + '\nContent: ' + text);
}

return [ { json: parsed } ];
